def parse_query_string(qs):
    """Parse a URL query string into a dict.

    - A key appearing once maps to its string value.
    - A key appearing more than once maps to a list of its values, in order.
    - A key with no '=' maps to the empty string.
    - Empty input returns an empty dict.
    """
    result = {}
    if not qs:
        return result

    for pair in qs.split("&"):
        if pair == "":
            continue
        key, sep, value = pair.partition("=")
        # No '=' present -> partition returns ('', '', '') for sep/value,
        # so value is already "" in that case.

        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[key] = [existing, value]
        else:
            result[key] = value

    return result
```

